index 0969320..e79bb63 100644
--- a/src/server.js
+++ b/src/server.js
@@ -13,7 +13,20 @@ export function createApp(inventory = Inventory.fromFile()) {

   router.get('/health', () => ({ status: 200, body: { status: 'ok' } }))

-  router.get('/books', () => ({ status: 200, body: inventory.list() }))
+  router.get('/books', (req) => {
+    const { author, tag } = req.query;
+    let books = inventory.list();
+
+    if (author) {
+        books = books.filter(book => book.author.toLowerCase().includes(author.toLowerCase()));
+    }
+
+    if (tag) {
+        books = books.filter(book => book.tags && book.tags.includes(tag));
+    }
+
+    return { status: 200, body: books };
+});

   router.get('/books/:id', ({ params }) => {
     const book = inventory.find(params.id)
