+const app = () => createApp(Inventory.fromFile());
+import { createApp } from '../src/server.js';
+import { Inventory } from '../src/inventory.js';
+
+const app = () => createApp(Inventory.fromFile());
+
+test('GET /books?author=martin filters by author', async () => {
+  const res = await app()({ method: 'GET', url: '/books?author=martin' });
+  assert.equal(res.status, 200);
+  assert.ok(res.body.every(book => book.author.toLowerCase().includes('martin')));
+});
+
+test('GET /books?tag=craft filters by tag', async () => {
+  const res = await app()({ method: 'GET', url: '/books?tag=craft' });
+  assert.equal(res.status, 200);
+  assert.ok(res.body.every(book => book.tags && book.tags.includes('craft')));
+});
+
+test('GET /books?author=martin&tag=craft filters by author and tag', async () => {
+  const res = await app()({ method: 'GET', url: '/books?author=martin&tag=craft' });
+  assert.equal(res.status, 200);
+  assert.ok(res.body.every(book => book.author.toLowerCase().includes('martin') && book.tags && book.tags.includes('craft')));
+});
